      const { note_id } = args;
      if (!isNonEmptyString(note_id)) {
        return errorResult('note_id is required and must be a non-empty string');
      }
      const note = notes.get(note_id);
      if (!note) {
        return errorResult(`note not found: ${note_id}`);
      }
      return textContent(
        `Note ${note.id}\nTitle: ${note.title}\nBody: ${note.body}`,
      );
    }
    default:
      return errorResult(`unknown tool: ${name}`);
  }
}
